package com.linkedList.anuj;

public class Node {

	public Node() {
		// TODO Auto-generated constructor stub
	}

	public int data;
	public Node next;
	public Node random;
	public int getData() {
		return data;
	}
	public void setData(int data) {
		this.data = data;
	}
	public Node getNext() {
		return next;
	}
	public void setNext(Node next) {
		this.next = next;
	}


}
